heTreasure_Reward[3009001][300] = {}	tDefendTheTreasure_Reward[3009001][300]["Num"] = 2	tDefendTheTreasure_Reward[3009001][300]["Attr"] = "0 2 0 2880 1"		tDefendTheTreasure_Reward[3009001][500] = {}	tDefendTheTreasure_Reward[3009001][500]["Num"] = 3	tDefendTheTreasure_Reward[3009001][500]["Attr"] = "0 3 0 2880 1"		tDefendTheTreasure_Reward[3009001][1000] = {}	tDefendTheTreasure_Reward[3009001][1000]["Num"] = 4	tDefendTheTreasure_Reward[3009001][1000]["Attr"] = "0 4 0 2880 1"	--个人奖励	tDefendTheTreasure_Reward[3009001][3200541] = {}	tDefendTheTreasure_Reward[3009001][3200541]["Attr"] = "0 2 0 2880 1"		------------------------------------------逻辑部分------------------------------------------传送function DefendTheTreasure_ChangeMap(nNpcId,nTarget)	if not (Get_UserMapId() == Get_NpcMapID(nNpcId)) then		return	end	--记录参与log	DefendTheTreasure_JionMark(nNpcId)	local nMapId = Get_NpcMapID(nTarget)	local nBoundX = Get_NpcPositionX(nTarget)	local nBoundY = Get_NpcPositionY(nTarget)	User_UserRandBoundTrans(nMapId,nBoundX,nBoundY,5,5)	User_TalkChannel2005(tDefendTheTreasure_Text["Msg"]["ChgMap"][nTarget])end--记录参与logfunction DefendTheTreasure_JionMark(nNpcId)	if not (nNpcId == tDefendTheTreasure_Cont["ActivityNpc"]) then 		return	end	local nEvent = tDefendTheTreasure_Stc["Event"] 	local nType = tDefendTheTreasure_Stc["Type"]["JoinMark"]	Task_StcReset(nEvent,nType)	if Task_ChkStcValue(nEvent,nType,"==",0) then		Task_SetStatistic(nEvent,nType,1,1)		Task_SetStcTimestamp(nEvent,nType,0)		Sys_SaveEmoneyBuy(tDefendTheTreasure_Log["Emoney"]["JoinMark"])	endendfunction DefendTheTreasure_Treasure(nNpcId)	if not Sys_ChkFullTime(tDefendTheTreasure_Cont["ActivityTime"]) then		LinkNpcGossipFunc_New(nNpcId,"1-2")		return	end	-- 新增背包判断	if not User_CheckLeftSpace(tDefendTheTreasure_Cont["SpacePesron"]) then		LinkNpcGossipFunc_New(nNpcId,"2-4")		return	end		local nTreasureId = tDefendTheTreasure_Cont["Treasure"]	if not Item_ChkMulItem(nTreasureId,nTreasureId,tDefendTheTreasure_Cont["TreasureNum"]) then		--数量不足		tNpcGossip[nNpcId]["Text221"] = string.format(tDefendTheTreasure_Text[nNpcId]["Text221"],tDefendTheTreasure_Cont["TreasureNum"])		LinkNpcGossipFunc_New(nNpcId,"2-2")		return	end				if Item_DelMulItem(nTreasureId,nTreasureId,tDefendTheTreasure_Cont["TreasureNum"]) then		local nEvent = tDefendTheTreasure_Stc["Event"] 		local nTaskType = tDefendTheTreasure_Stc["Type"]["TaskMark"]			local nPointType = tDefendTheTreasure_Stc["Type"]["Point"]			Task_SetStatistic(nEvent,nTaskType,1,1)		Task_SetStcTimestamp(nEvent,nTaskType,0)		Task_AddStatistic(nEvent,nPointType,tDefendTheTreasure_Cont["TreasurePoint"],1)		Task_SetStcTimestamp(nEvent,nPointType,0)				local nMark = User_AddExpOrCultureValue(tDefendTheTreasure_Reward[nTreasureId]["RewardExpTime"],tDefendTheTreasure_Reward[nTreasureId]["FullExpTime"])		--新增给明亮星陨石		local sAttr = tDefendTheTreasure_Reward[3009001][3200541]["Attr"]		Item_AddNewItem(tDefendTheTreasure_Reward[3009001]["Id"],sAttr)				User_AddCultivation(tDefendTheTreasure_Reward[nTreasureId]["RewardCultivation"])		User_EffectAdd("self",tDefendTheTreasure_Cont["Effect"])		if nMark == 1 then 			Sys_SaveActionFestivalLog(tDefendTheTreasure_Log["HandIn"][3200541]["ExpTime"])			Sys_MsgBox(tDefendTheTreasure_Text["Reward"][nTreasureId]["RewardExpTime"])		elseif  nMark == 2 then			Sys_SaveActionFestivalLog(tDefendTheTreasure_Log["HandIn"][3200541]["FullExpTime"])			Sys_MsgBox(tDefendTheTreasure_Text["Reward"][nTreasureId]["RewardCultivation"])		end		--帮派贡献函数		DefendTheTreasure_GuildPoint(tDefendTheTreasure_Cont["TreasurePoint"])		if Item_ChkItem(tDefendTheTreasure_Cont["SeniorTreasure"]) then			LinkNpcGossipFunc_New(nNpcId,"2-1")			return		end			endendfunction DefendTheTreasure_SeniorTreasure(nNpcId)	if not Sys_ChkFullTime(tDefendTheTreasure_Cont["ActivityTime"]) then		LinkNpcGossipFunc_New(nNpcId,"1-2")		return	end			local nTreasureId = tDefendTheTreasure_Cont["SeniorTreasure"]		if not Item_ChkItem(nTreasureId) then		LinkNpcGossipFunc_New(nNpcId,"2-3")		return	end				if not User_CheckLeftSpace(tDefendTheTreasure_Cont["Space"]) then		LinkNpcGossipFunc_New(nNpcId,"2-4")		return	end				if Item_DelItem(nTreasureId) then		local nEvent = tDefendTheTreasure_Stc["Event"] 		local nPointType = tDefendTheTreasure_Stc["Type"]["Point"]			Task_AddStatistic(nEvent,nPointType,tDefendTheTreasure_Cont["SeniorTreasurePoint"],1)		Task_SetStcTimestamp(nEvent,nPointType,0)			local flat,tTable = Probabil_RandomAward(tDefendTheTreasure_Reward[nTreasureId],1)		local nAwardItemId = tTable[1]["tAward"][1]["GetItem"]				--判断纪念币是否超出10		if nAwardItemId == tDefendTheTreasure_Reward[3200542][1][7]["GetItem"] then			local nCoin = Get_SysDynaGlobalData(tDefendTheTreasure_Cont["GlobalId"],3)			if nCoin >= tDefendTheTreasure_Cont["CoinMax"] then				nAwardItemId = tDefendTheTreasure_Reward[3200542][1][1]["GetItem"]			else				nCoin = nCoin + 1				Sys_SetSynaGlobalData3(tDefendTheTreasure_Cont["GlobalId"],nCoin)			end				end		local sTips =  string.format(tDefendTheTreasure_Text["Reward"][3200542],Get_ItemtypeName(nAwardItemId))		local sLog = string.format(tDefendTheTreasure_Log["HandIn"][3200542],nAwardItemId)			Item_AddNewItem(nAwardItemId,"")		Sys_SaveActionFestivalLog(sLog)		Sys_SaveEmoneyBuy(tDefendTheTreasure_Log["Emoney"]["SeniorTreasure"])		Sys_MsgBox(sTips)				--帮派贡献函数		DefendTheTreasure_GuildPoint(tDefendTheTreasure_Cont["SeniorTreasurePoint"])		if Item_ChkItem(tDefendTheTreasure_Cont["SeniorTreasure"]) then			LinkNpcGossipFunc_New(nNpcId,"2-1")			return		end			endendfunction DefendTheTreasure_GuildPoint(nPoint)	local nGuildId = Get_UserGuildId()	if (nGuildId == nil) or (nGuildId <= 0) then		return	end		--二级以下不参加排名	if not (Get_UserSynLevel(nGuildId) >= tDefendTheTreasure_Cont["GuildLev"]) then		return	end		--列表中已存在的帮派	for i,v in ipairs(tDefendTheTreasure_RankList) do		if v.GuildId == nGuildId then			v.GuildPoint = v.GuildPoint + nPoint			v.GuildDayPoint = v.GuildDayPoint + nPoint			return		end	end		--新帮派加入排行	local tNewRankList = {}	tNewRankList.GuildId = nGuildId	tNewRankList.GuildPoint = nPoint	tNewRankList.GuildDayPoint = nPoint	table.insert(tDefendTheTreasure_RankList,tNewRankList)end--领取帮派荣誉大赏function DefendTheTreasure_GuildRewardTalk(nNpcId)	local nEvent = tDefendTheTreasure_Stc["Event"] 	local nGuildDayPoint = DefendTheTreasure_GuildDayPoint()	Task_StcReset(nEvent,tDefendTheTreasure_Stc["Type"]["GuildReward"][100])	Task_StcReset(nEvent,tDefendTheTreasure_Stc["Type"]["GuildReward"][300])	Task_StcReset(nEvent,tDefendTheTreasure_Stc["Type"]["GuildReward"][500])	Task_StcReset(nEvent,tDefendTheTreasure_Stc["Type"]["GuildReward"][1000])	tNpcGossip[11141]["Text318"] = string.format(tDefendTheTreasure_Text[11141]["Text318"],nGuildDayPoint)	if not Task_ChkStcValue(nEvent,tDefendTheTreasure_Stc["Type"]["GuildReward"][100],"==",0) then		tNpcGossip[11141]["Option311"] = tDefendTheTreasure_Text[11141]["Option311"]..tDefendTheTreasure_Text["Msg"]["GuildReward"]	else		tNpcGossip[11141]["Option311"] = tDefendTheTreasure_Text[11141]["Option311"]	end	if not Task_ChkStcValue(nEvent,tDefendTheTreasure_Stc["Type"]["GuildReward"][300],"==",0) then		tNpcGossip[11141]["Option312"] = tDefendTheTreasure_Text[11141]["Option312"]..tDefendTheTreasure_Text["Msg"]["GuildReward"]	else		tNpcGossip[11141]["Option312"] = tDefendTheTreasure_Text[11141]["Option312"]	end	if not Task_ChkStcValue(nEvent,tDefendTheTreasure_Stc["Type"]["GuildReward"][500],"==",0) then		tNpcGossip[11141]["Option313"] = tDefendTheTreasure_Text[11141]["Option313"]..tDefendTheTreasure_Text["Msg"]["GuildReward"]	else		tNpcGossip[11141]["Option313"] = tDefendTheTreasure_Text[11141]["Option313"]	end	if not Task_ChkStcValue(nEvent,tDefendTheTreasure_Stc["Type"]["GuildReward"][1000],"==",0) then		tNpcGossip[11141]["Option314"] = tDefendTheTreasure_Text[11141]["Option314"]..tDefendTheTreasure_Text["Msg"]["GuildReward"]	else		tNpcGossip[11141]["Option314"] = tDefendTheTreasure_Text[11141]["Option314"]	end		LinkNpcGossipFunc_New(nNpcId,"3-1")end--领取xx点气力值。function DefendTheTreasure_GuildReward(nNpcId,nPoint)	if not Sys_ChkFullTime(tDefendTheTreasure_Cont["ActivityTime"]) then		LinkNpcGossipFunc_New(nNpcId,"1-2")		return	end	local nGuildDayPoint = DefendTheTreasure_GuildDayPoint()	if nGuildDayPoint < nPoint then		tNpcGossip[nNpcId]["Text321"] = string.format(tDefendTheTreasure_Text[nNpcId]["Text321"],nPoint)		LinkNpcGossipFunc_New(nNpcId,"3-2")		return	end	--新增背包判断	if not User_CheckLeftSpace(tDefendTheTreasure_Cont["SpaceMax"]) then		LinkNpcGossipFunc_New(nNpcId,"2-4")		return	end			local nEvent = tDefendTheTreasure_Stc["Event"] 	local nType = tDefendTheTreasure_Stc["Type"]["GuildReward"][nPoint]	Task_StcReset(nEvent,nType)	--已领取奖励	if not Task_ChkStcValue(nEvent,nType,"==",0) then		LinkNpcGossipFunc_New(nNpcId,"3-3")		return	end		Task_SetStatistic(nEvent,nType,1,1)	Task_SetStcTimestamp(nEvent,nType,0)		local nNum = tDefendTheTreasure_Reward[3009001][nPoint]["Num"]	local sAttr = tDefendTheTreasure_Reward[3009001][nPoint]["Attr"]		local nAddStrength = tDefendTheTreasure_Reward["GuildReward"][nPoint]	local sLog = string.format(tDefendTheTreasure_Log["GuildReward"],nAddStrength,nNum)	local sTip = string.format(tDefendTheTreasure_Text["Msg"]["GuildRewardGet"],nAddStrength,nNum)	User_AddStrengthValue(nAddStrength)	--新增给明亮星陨石	Item_AddNewItem(tDefendTheTreasure_Reward[3009001]["Id"],sAttr)		Sys_SaveActionFestivalLog(sLog)	Sys_MsgBox(sTip)		User_EffectAdd("self",tDefendTheTreasure_Cont["Effect"])endfunction DefendTheTreasure_GuildDayPoint()	local nGuildId = Get_UserGuildId()	for i,v in ipairs(tDefendTheTreasure_RankList) do		if v.GuildId == nGuildId then			return v.GuildDayPoint		end	end	return 0endfunction DefendTheTreasure_Rank(nNpcId)	table.sort(tDefendTheTreasure_RankList,DefendTheTreasure_Comp)	local nWangId =Get_SysDynaGlobalData(tDefendTheTreasure_Cont["GlobalId"],2)		Sys_DialogText(tDefendTheTreasure_Text[11141]["Text511"])	Sys_DialogText(tDefendTheTreasure_Text[11141]["Text512"])	Sys_DialogText(tDefendTheTreasure_Text[11141]["Text513"])	for i,v in ipairs(tDefendTheTreasure_RankList) do		if v.GuildDayPoint > 0 and (i <= 10) then			local sGuildName = Get_UserSynDicateName(v.GuildId)			local sStr = string.format(tDefendTheTreasure_Text[11141]["Text515"],i,v.GuildDayPoint,sGuildName)			Sys_DialogText(sStr)		end	end	Sys_DialogText(tDefendTheTreasure_Text[11141]["Text514"])	if nWangId == Get_UserId() then		Sys_DialogOption(tDefendTheTreasure_Text[11141]["Option511"],"</F>DefendTheTreasure_WangReward</N>"..nNpcId)	end	Sys_DialogOption(tDefendTheTreasure_Text[11141]["Option512"])	Sys_DialogFace(nNpcId)	Sys_DialogEnd()endfunction DefendTheTreasure_Comp(tA,tB)	return tA.GuildDayPoint > tB.GuildDayPointendfunction DefendTheTreasure_WangReward(nNpcId)	if not Sys_ChkFullTime(tDefendTheTreasure_Cont["ActivityTime2"]) then		LinkNpcGossipFunc_New(nNpcId,"1-2")		return	end	local nWangId =Get_SysDynaGlobalData(tDefendTheTreasure_Cont["GlobalId"],2)	if not nWangId == Get_UserId() then		return	end	local nEvent = tDefendTheTreasure_Stc["Event"] 	local nType = tDefendTheTreasure_Stc["Type"]["WangReward"]	Task_StcReset(nEvent,nType)	--已领取奖励	if not Task_ChkStcValue(nEvent,nType,"==",0) then		LinkNpcGossipFunc_New(nNpcId,"3-3")		return	end			if not User_CheckLeftSpace(tDefendTheTreasure_Reward["WangReward"]["Space"]) then		LinkNpcGossipFunc_New(nNpcId,"5-3")		return	end				Task_SetStatistic(nEvent,nType,1,1)	Task_SetStcTimestamp(nEvent,nType,0)			Item_AddNewItem(tDefendTheTreasure_Reward["WangReward"]["ItemId"],tDefendTheTreasure_Reward["WangReward"]["Attr"])	Sys_SaveActionFestivalLog(tDefendTheTreasure_Log["WangReward"])	Sys_MsgBox(tDefendTheTreasure_Text["Msg"]["WangRewardGet"])	endfunction DefendTheTreasure_Monster(nMonsterId)	if not Sys_ChkFullTime(tDefendTheTreasure_Cont["ActivityTime"]) then		return	end		if nMonsterId == tDefendTheTreasure_Cont["Monster"] then		local nMapId = tDefendTheTreasure_Cont["MapId"]		Sys_SetTempData(1,nMapId,nMonsterId,0)	end		if not User_CheckLeftSpace(tDefendTheTreasure_Cont["Space"]) then		User_TalkChannel2005(tDefendTheTreasure_Text["Msg"]["MonsterSpace"])		return	end		DefendTheTreasure_DropTreasure(nMonsterId)	if not User_CheckLeftSpace(tDefendTheTreasure_Cont["Space"]) then		User_TalkChannel2005(tDefendTheTreasure_Text["Msg"]["MonsterSpace"])		return	end	DefendTheTreasure_DropSeniorTreasure(nMonsterId)endfunction DefendTheTreasure_DropTreasure(nMonsterId)	local nTreasureId = tDefendTheTreasure_Cont["Treasure"]	if Sys_Random(tDefendTheTreasure_Cont["TreasureDrop"][nMonsterId],10000) then		local nEvent = tDefendTheTreasure_Stc["Event"] 		local nType = tDefendTheTreasure_Stc["Type"]["TreasureDrop"]				local nTipType = tDefendTheTreasure_Stc["Type"]["Tip"]				Task_StcReset(nEvent,nType)		Task_StcReset(nEvent,nTipType)		if Task_ChkStcValue(nEvent,nType,">=",tDefendTheTreasure_Stc["Type"]["TreasureMaxDrop"]) then			return		end					Task_AddStatistic(nEvent,nType,1,1)		Task_SetStcTimestamp(nEvent,nType,0)			Item_AddNewItem(nTreasureId,"")		User_EffectAdd("self",tDefendTheTreasure_Cont["Effect1"])		Sys_SaveActionFestivalLog(string.format(tDefendTheTreasure_Log["GetTaskItem"],nTreasureId))		if Item_ChkMulItem(nTreasureId,nTreasureId,tDefendTheTreasure_Cont["TreasureNum"]) then			if Task_ChkStcValue(nEvent,nTipType,">=",1) then				return			end			Task_AddStatistic(nEvent,nTipType,1,1)			Task_SetStcTimestamp(nEvent,nTipType,0)					Sys_MsgBox(tDefendTheTreasure_Text["Msg"]["TaskOK"],"NpcPosition_PathFind</N>11141")		else			User_TalkChannel2005(string.format(tDefendTheTreasure_Text["Msg"]["GetTreasure"],tDefendTheTreasure_Text["Msg"]["Kill"][nMonsterId]))		end	endendfunction DefendTheTreasure_DropSeniorTreasure(nMonsterId)	if Sys_Random(tDefendTheTreasure_Cont["SeniorTreasureDrop"][nMonsterId],10000) then		local nTreasureId = tDefendTheTreasure_Cont["SeniorTreasure"]		local nEvent = tDefendTheTreasure_Stc["Event"] 		local nType = tDefendTheTreasure_Stc["Type"]["SeniorTreasureDrop"]				Task_StcReset(nEvent,nType)		if Task_ChkStcValue(nEvent,nType,">=",tDefendTheTreasure_Stc["Type"]["SeniorTreasureMaxDrop"]) then			User_TalkChannel2005(tDefendTheTreasure_Text["Msg"]["GetSeniorTreasureMax"])			return		end					Task_AddStatistic(nEvent,nType,1,1)		Task_SetStcTimestamp(nEvent,nType,0)			Item_AddNewItem(nTreasureId,"")		User_EffectAdd("self",tDefendTheTreasure_Cont["Effect1"])		Sys_SaveActionFestivalLog(string.format(tDefendTheTreasure_Log["GetTaskItem"],nTreasureId))		User_TalkChannel2005(string.format(tDefendTheTreasure_Text["Msg"]["GetSeniorTreasure"],tDefendTheTreasure_Text["Msg"]["Kill"][nMonsterId]))	endend--每天清零function DefendTheTreasure_DayReset()	if not Sys_ChkFullTime(tDefendTheTreasure_Cont["ActivityTime2"]) then		return	end	if (Get_SysDynaGlobalData(tDefendTheTreasure_Cont["Reset"],1) == 0) then		Sys_SetSynaGlobalData1(tDefendTheTreasure_Cont["Reset"],1)			table.sort(tDefendTheTreasure_RankList,DefendTheTreasure_Comp)		local nGuildId = tDefendTheTreasure_RankList[1]["GuildId"]		local nWangId = Get_SynWangId(tDefendTheTreasure_RankList[1]["GuildId"])		Sys_SetSynaGlobalData1(tDefendTheTreasure_Cont["GlobalId"],nGuildId)		Sys_SetSynaGlobalData2(tDefendTheTreasure_Cont["GlobalId"],nWangId)		Sys_SetSynaGlobalData3(tDefendTheTreasure_Cont["GlobalId"],0)		--清空排行榜		tDefendTheTreasure_RankList = {}	endendfunction DefendTheTreasure_DayReset2()	if not Sys_ChkFullTime(tDefendTheTreasure_Cont["ActivityTime2"]) then		return	end	if (Get_SysDynaGlobalData(tDefendTheTreasure_Cont["Reset"],1) > 0) then		Sys_SetSynaGlobalData1(tDefendTheTreasure_Cont["Reset"],0)	endendfunction DefendTheTreasure_CreatMonster()	if not Sys_ChkFullTime(tDefendTheTreasure_Cont["ActivityTime2"]) then		return	end		local sName = tDefendTheTreasure_Text["Msg"]["TombRobbingLeader"]		local nMapId = tDefendTheTreasure_Cont["MapId"]	local nMonsterId = tDefendTheTreasure_Cont["Monster"]	local nMonsterNum = Get_SysTempData(1,nMapId,nMonsterId)	if nMonsterNum < 1 then	-- if not (Monster_GetMonsterByName(tDefendTheTreasure_Cont["MapId"],sName) > 0) then		for i =1,#tDefendTheTreasure_Cont["CreatPos"] do			local nGenId = tDefendTheTreasure_Cont["CreatPos"][i][1]			local nPosX = tDefendTheTreasure_Cont["CreatPos"][i][2]			local nPosY = tDefendTheTreasure_Cont["CreatPos"][i][3]			local sTip = string.format(tDefendTheTreasure_Text["Msg"]["CreatMonster"],nPosX,nPosY)			Monster_AddMonster(tDefendTheTreasure_Cont["MapId"],nPosX,nPosY,nGenId,tDefendTheTreasure_Cont["Monster"])			Sys_SetTempData(1,nMapId,nMonsterId,nMonsterNum+1)			if i >= (#tDefendTheTreasure_Cont["CreatPos"]-2) then				Map_SendBroadcastMsg(tDefendTheTreasure_Cont["MapId"],sTip)			end		end	endend--------------------------------------------nPC-------------------------------------tNpcFace[4200] = 14tNpcGossip[11140] = tNpcGossip[11140] or DefaultNpc:new{}tNpcGossip[11140]["OptionHidden"] = 1tNpcFace[4201] = 95tNpcGossip[11141] = tNpcGossip[11141] or DefaultNpc:new{}tNpcGossip[11141]["OptionHidden"] = 1--守陵将军--活动前 or 等级不足tNpcGossip[11140]["Text1-1"] = {111,112,113,114}tNpcGossip[11140]["tOption1-1"] = {111}tNpcGossip[11140]["Text111"] = tDefendTheTreasure_Text[11140]["Text111"]tNpcGossip[11140]["Text112"] = tDefendTheTreasure_Text[11140]["Text112"]tNpcGossip[11140]["Text113"] = tDefendTheTreasure_Text[11140]["Text113"]tNpcGossip[11140]["Text114"] = tDefendTheTreasure_Text[11140]["Text114"]tNpcGossip[11140]["Option111"] = tDefendTheTreasure_Text[11140]["Option111"]tNpcGossip[11140]["ChkFunc1-1"] = function ()	return Sys_ChkFullTime(tDefendTheTreasure_Cont["BeforeActivityTime"])end--等级不足tNpcGossip[11140]["Te